SELECT p1.c1 AS result
FROM (
    SELECT (SELECT COALESCE(JSON_SCALAR(CASE WHEN JSON_VALUE(sh4.v1, '$.type()') = 'double' AND JSON_VALUE(sh4.v1, '$') IN ('Nan', 'Inf', '-Inf') THEN DECODE(JSON_VALUE(sh4.v1, '$'), 'Nan', 'NaN', 'Inf', 'Infinity', '-Infinity') WHEN JSON_VALUE(sh4.v1, '$.type()') = 'double' OR (JSON_VALUE(sh4.v1, '$.type()') = 'number' AND NOT (JSON_VALUE(sh4.v1, '$.type()') = 'number' AND JSON_VALUE(sh4.v1, '$' RETURNING NUMBER) = TRUNC(JSON_VALUE(sh4.v1, '$' RETURNING NUMBER)))) THEN CASE WHEN JSON_VALUE(sh4.v1, '$' RETURNING BINARY_DOUBLE) = 0 THEN '0.0' WHEN ABS(TO_NUMBER(JSON_VALUE(sh4.v1, '$') DEFAULT NULL ON CONVERSION ERROR)) >= 0.001 AND ABS(TO_NUMBER(JSON_VALUE(sh4.v1, '$') DEFAULT NULL ON CONVERSION ERROR)) < 10000000 THEN TO_CHAR(TO_NUMBER(JSON_VALUE(sh4.v1, '$') DEFAULT NULL ON CONVERSION ERROR), 'FM9999990.0999999999999999999999') ELSE REGEXP_REPLACE(REPLACE(NVL(TO_CHAR(NULLIF(TO_NUMBER(JSON_VALUE(sh4.v1, '$') DEFAULT NULL ON CONVERSION ERROR), 0), 'FM9.9999999999999999EEEE'), REGEXP_REPLACE(JSON_VALUE(sh4.v1, '$'), '^(-?[0-9]+)E', '\1.0E')), '.E', '.0E'), 'E\+?(-?)0*([0-9])', 'E\1\2') END ELSE JSON_VALUE(sh4.v1, '$') END), JSON_SCALAR(CASE WHEN JSON_VALUE(sh4.v1, '$.type()') = 'string' THEN JSON_VALUE(sh4.v1, '$' RETURNING CLOB) END)) FROM (SELECT /*+ NO_MERGE */ JSON_SCALAR((SELECT REGEXP_REPLACE(LTRIM(TO_CHAR(sh3.v1, 'SYYYY-MM-DD')), '^-[0-9]{4}', TO_CHAR(EXTRACT(YEAR FROM sh3.v1) + 1, 'FM0000')) FROM (SELECT /*+ NO_MERGE */ ((SELECT (CAST(ADD_MONTHS(TRUNC(CAST(sh2.v1 AS DATE), 'MM'), sh2.v2) AS TIMESTAMP) + NUMTODSINTERVAL(LEAST(EXTRACT(DAY FROM sh2.v1), EXTRACT(DAY FROM LAST_DAY(ADD_MONTHS(TRUNC(CAST(sh2.v1 AS DATE), 'MM'), sh2.v2)))) - 1, 'DAY') + (sh2.v1 - CAST(TRUNC(CAST(sh2.v1 AS DATE)) AS TIMESTAMP))) FROM (SELECT /*+ NO_MERGE */ TO_TIMESTAMP(CASE WHEN ASCII(CASE WHEN JSON_VALUE(JSON('"-0044-03-15"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"-0044-03-15"'), '$') END) < 49 THEN REGEXP_REPLACE(CASE WHEN JSON_VALUE(JSON('"-0044-03-15"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"-0044-03-15"'), '$') END, '^(-[0-9]{4}|0000)', TO_CHAR(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"-0044-03-15"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"-0044-03-15"'), '$') END, '^-?[0-9]{4}')) - 1, 'FM0000')) ELSE CASE WHEN JSON_VALUE(JSON('"-0044-03-15"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"-0044-03-15"'), '$') END END, 'SYYYY-MM-DD') AS v1, ((CASE WHEN SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 1, 1) = '-' THEN -1 WHEN CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END IS NOT NULL THEN 1 END * (COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, '^(-?)P((-?[0-9.]+)Y)?((-?[0-9.]+)M)?((-?[0-9.]+)W)?((-?[0-9.]+)D)?', 1, 1, NULL, 3)), 0) * 12 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, '^(-?)P((-?[0-9.]+)Y)?((-?[0-9.]+)M)?((-?[0-9.]+)W)?((-?[0-9.]+)D)?', 1, 1, NULL, 5)), 0)))) AS v2) sh2) + NUMTODSINTERVAL(((CASE WHEN SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 1, 1) = '-' THEN -1 WHEN CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END IS NOT NULL THEN 1 END * (COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, '^(-?)P((-?[0-9.]+)Y)?((-?[0-9.]+)M)?((-?[0-9.]+)W)?((-?[0-9.]+)D)?', 1, 1, NULL, 7)), 0) * 7 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, '^(-?)P((-?[0-9.]+)Y)?((-?[0-9.]+)M)?((-?[0-9.]+)W)?((-?[0-9.]+)D)?', 1, 1, NULL, 9)), 0)))), 'DAY') + NUMTODSINTERVAL(((SELECT CASE WHEN 1 = 1 THEN TRUNC(sh1.v1 / 86400) * 86400 ELSE sh1.v1 END FROM (SELECT /*+ NO_MERGE */ (CASE WHEN SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 1, 1) = '-' THEN -1 WHEN CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END IS NOT NULL THEN 1 END * (COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 2)), 0) * 3600 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 4)), 0) * 60 + COALESCE(TO_NUMBER(REGEXP_SUBSTR(CASE WHEN JSON_VALUE(JSON('"P1D"'), '$.type()') = 'string' THEN JSON_VALUE(JSON('"P1D"'), '$') END, 'T((-?[0-9.]+)H)?((-?[0-9.]+)M)?((-?[0-9.]+)S)?$', 1, 1, NULL, 6)), 0))) AS v1) sh1)), 'SECOND')) AS v1) sh3)) AS v1) sh4) AS c1
) p1